function minimumPushes(word) {
  const count = new Array(26).fill(0);
  for (const ch of word) {
    count[ch.charCodeAt(0) - 97]++;
  }
  count.sort((a, b) => b - a);
  let pushes = 0;
  for (let i = 0; i < 26; i++) {
    if (count[i] === 0) {
      break;
    }
    const cost = Math.floor(i / 8) + 1;
    pushes += count[i] * cost;
  }
  return pushes;
}

