function minimumPushes(word) {
  // Give every distinct letter a press count 1..4, with at most 8 letters per press count
  // (one per key); search all such choices with memoisation.
  const freq = {};
  for (const ch of word) freq[ch] = (freq[ch] || 0) + 1;
  const letters = Object.keys(freq);
  const memo = new Map();
  const solve = (idx, used) => {
    if (idx === letters.length) return 0;
    const key = idx + ':' + used.join(',');
    if (memo.has(key)) return memo.get(key);
    let best = Infinity;
    for (let press = 1; press <= 4; press++) {
      if (used[press - 1] === 8) continue;
      const next = used.slice();
      next[press - 1]++;
      best = Math.min(best, press * freq[letters[idx]] + solve(idx + 1, next));
    }
    memo.set(key, best);
    return best;
  };
  return solve(0, [0, 0, 0, 0]);
}

