function generate(rand, size) {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz'.split('');
  for (let i = 25; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [alphabet[i], alphabet[j]] = [alphabet[j], alphabet[i]]; }
  const distinct = size === 'large' ? (rand() < 0.6 ? 26 : 9 + Math.floor(rand() * 18)) : 1 + Math.floor(rand() * 26);
  const length = size === 'large' ? 8000 + Math.floor(rand() * 2001) : 1 + Math.floor(rand() * 40);
  // Skewed weights so frequencies differ a lot between letters.
  const weights = Array.from({ length: distinct }, () => Math.pow(rand(), 3) + 0.01);
  const total = weights.reduce((a, b) => a + b, 0);
  let word = '';
  for (let i = 0; i < length; i++) {
    let r = rand() * total, k = 0;
    while (k < distinct - 1 && r >= weights[k]) { r -= weights[k]; k++; }
    word += alphabet[k];
  }
  return [word];
}
